42	/**
43	 * Test audit manager invocation by making assertions
44	 * about the statistics of audit request execution
45	 * {@link org.apache.hadoop.fs.s3a.Statistic#AUDIT_REQUEST_EXECUTION}
46	 * and
47	 * {@link org.apache.hadoop.fs.s3a.Statistic#AUDIT_FAILURE}.
48	 */
49	public class ITestAuditManager extends AbstractS3ACostTest {
50	
51	  public ITestAuditManager() {
52	    super(true);
53	  }
54	
55	  @Override
56	  public Configuration createConfiguration() {
57	    Configuration conf = super.createConfiguration();
58	    resetAuditOptions(conf);
59	    enableLoggingAuditor(conf);
60	    conf.set(AUDIT_REQUEST_HANDLERS,
61	        SimpleAWSRequestHandler.CLASS);
62	    return conf;
63	  }
64	
65	  /**
66	   * Get the FS IOStatistics.
67	   * @return the FS live IOSTats.
68	   */
69	  private IOStatistics iostats() {
70	    return getFileSystem().getIOStatistics();
71	  }
72	
73	  /**
74	   * Verify that operations outside a span are rejected
75	   * by ensuring that the thread is outside a span, create
76	   * a write operation helper, then
77	   * reject it.
78	   */
79	  @Test
80	  public void testInvokeOutOfSpanRejected() throws Throwable {
81	    describe("Operations against S3 will be rejected outside of a span");
82	    final S3AFileSystem fs = getFileSystem();
83	    final long failures0 = lookupCounterStatistic(iostats(),
84	        AUDIT_FAILURE.getSymbol());
85	    final long exec0 = lookupCounterStatistic(iostats(),
86	        AUDIT_REQUEST_EXECUTION.getSymbol());
87	    // API call
88	    // create and close a span, so the FS is not in a span.
89	    fs.createSpan("span", null, null).close();
90	
91	    // this will be out of span
92	    final WriteOperationHelper writer
93	        = fs.getWriteOperationHelper();
94	
95	    // which can be verified
96	    Assertions.assertThat(writer.getAuditSpan())
97	        .matches(s -> !s.isValidSpan(), "Span is not valid");
98	
99	    // an S3 API call will fail and be mapped to access denial.
100	    final AccessDeniedException ex = intercept(
101	        AccessDeniedException.class, UNAUDITED_OPERATION, () ->
102	            writer.listMultipartUploads("/"));
103	
104	    // verify the type of the inner cause, throwing the outer ex
105	    // if it is null or a different class
106	    if (!(ex.getCause() instanceof AuditFailureException)) {
107	      throw ex;
108	    }
109	
110	    assertThatStatisticCounter(iostats(), AUDIT_REQUEST_EXECUTION.getSymbol())
111	        .isGreaterThan(exec0);
112	    assertThatStatisticCounter(iostats(), AUDIT_FAILURE.getSymbol())
113	        .isGreaterThan(failures0);
114	  }
115	
116	  @Test
117	  public void testRequestHandlerBinding() throws Throwable {
118	    describe("Verify that extra request handlers can be added and that they"
119	        + " will be invoked during request execution");
120	    final long baseCount = SimpleAWSRequestHandler.getInvocationCount();
121	    final S3AFileSystem fs = getFileSystem();
122	    final long exec0 = lookupCounterStatistic(iostats(),
123	        AUDIT_REQUEST_EXECUTION.getSymbol());
124	    // API call to a known path, `getBucketLocation()` does not always result in an API call.
125	    fs.listStatus(path("/"));
126	    // which MUST have ended up calling the extension request handler
127	    Assertions.assertThat(SimpleAWSRequestHandler.getInvocationCount())
128	        .describedAs("Invocation count of plugged in request handler")
129	        .isGreaterThan(baseCount);
130	    assertThatStatisticCounter(iostats(), AUDIT_REQUEST_EXECUTION.getSymbol())
131	        .isGreaterThan(exec0);
132	    assertThatStatisticCounter(iostats(), AUDIT_FAILURE.getSymbol())
133	        .isZero();
134	  }
