41	/**
42	 * A OutputFormat that sends the reduce output to a SQL table.
43	 * <p> 
44	 * {@link DBOutputFormat} accepts &lt;key,value&gt; pairs, where 
45	 * key has a type extending DBWritable. Returned {@link RecordWriter} 
46	 * writes <b>only the key</b> to the database with a batch SQL query.  
47	 * 
48	 */
49	@InterfaceAudience.Public
50	@InterfaceStability.Stable
51	public class DBOutputFormat<K  extends DBWritable, V> 
52	extends OutputFormat<K,V> {
53	
54	  private static final Logger LOG =
55	      LoggerFactory.getLogger(DBOutputFormat.class);
56	  public String dbProductName = "DEFAULT";
57	
58	  public void checkOutputSpecs(JobContext context) 
59	      throws IOException, InterruptedException {}
60	
61	  public OutputCommitter getOutputCommitter(TaskAttemptContext context) 
62	      throws IOException, InterruptedException {
63	    return new FileOutputCommitter(FileOutputFormat.getOutputPath(context),
64	                                   context);
65	  }
66	
67	  /**
68	   * A RecordWriter that writes the reduce output to a SQL table
69	   */
70	  @InterfaceStability.Evolving
71	  public class DBRecordWriter 
72	      extends RecordWriter<K, V> {
73	
74	    private Connection connection;
75	    private PreparedStatement statement;
76	
77	    public DBRecordWriter() throws SQLException {
78	    }
79	
80	    public DBRecordWriter(Connection connection
81	        , PreparedStatement statement) throws SQLException {
82	      this.connection = connection;
83	      this.statement = statement;
84	      this.connection.setAutoCommit(false);
85	    }
86	
87	    public Connection getConnection() {
88	      return connection;
89	    }
90	    
91	    public PreparedStatement getStatement() {
92	      return statement;
93	    }
94	    
95	    /** {@inheritDoc} */
96	    public void close(TaskAttemptContext context) throws IOException {
97	      try {
98	        statement.executeBatch();
99	        connection.commit();
100	      } catch (SQLException e) {
101	        try {
102	          connection.rollback();
103	        }
104	        catch (SQLException ex) {
105	          LOG.warn(StringUtils.stringifyException(ex));
106	        }
107	        throw new IOException(e.getMessage());
108	      } finally {
109	        try {
110	          statement.close();
111	          connection.close();
112	        }
113	        catch (SQLException ex) {
114	          throw new IOException(ex.getMessage());
115	        }
116	      }
117	    }
118	
119	    /** {@inheritDoc} */
120	    public void write(K key, V value) throws IOException {
121	      try {
122	        key.write(statement);
123	        statement.addBatch();
124	      } catch (SQLException e) {
125	        e.printStackTrace();
126	      }
127	    }
128	  }
129	
130	  /**
131	   * Constructs the query used as the prepared statement to insert data.
132	   * 
133	   * @param table
134	   *          the table to insert into
135	   * @param fieldNames
136	   *          the fields to insert into. If field names are unknown, supply an
137	   *          array of nulls.
138	   */
139	  public String constructQuery(String table, String[] fieldNames) {
140	    if(fieldNames == null) {
141	      throw new IllegalArgumentException("Field names may not be null");
142	    }
