50	  protected static ValueAggregatorDescriptor getValueAggregatorDescriptor(
51	      String spec, Configuration conf) {
52	    if (spec == null)
53	      return null;
54	    String[] segments = spec.split(",", -1);
55	    String type = segments[0];
56	    if (type.compareToIgnoreCase("UserDefined") == 0) {
57	      String className = segments[1];
58	      return new UserDefinedValueAggregatorDescriptor(className, conf);
59	    }
60	    return null;
61	  }
62	
63	  protected static ArrayList<ValueAggregatorDescriptor> getAggregatorDescriptors(
64	      Configuration conf) {
65	    int num = conf.getInt(DESCRIPTOR_NUM, 0);
66	    ArrayList<ValueAggregatorDescriptor> retv = 
67	      new ArrayList<ValueAggregatorDescriptor>(num);
68	    for (int i = 0; i < num; i++) {
69	      String spec = conf.get(DESCRIPTOR + "." + i);
70	      ValueAggregatorDescriptor ad = getValueAggregatorDescriptor(spec, conf);
71	      if (ad != null) {
72	        retv.add(ad);
73	      }
74	    }
75	    return retv;
76	  }
