138	bool Find::HandlePath(const std::string &path, const std::string &name,
139	                      const uint32_t max_depth) const {
140	  // Building a URI object from the given path
141	  auto uri = hdfs::parse_path_or_exit(path);
142	
143	  const auto fs = hdfs::doConnect(uri, true);
144	  if (!fs) {
145	    std::cerr << "Could not connect the file system." << std::endl;
146	    return false;
147	  }
148	
149	  const auto promise = std::make_shared<std::promise<void>>();
150	  std::future<void> future(promise->get_future());
151	  auto final_status = hdfs::Status::OK();
152	
153	  /**
154	   * Keep requesting more until we get the entire listing. Set the promise
155	   * when we have the entire listing to stop.
156	   *
157	   * Find guarantees that the handler will only be called once at a time,
158	   * so we do not need any locking here. It also guarantees that the handler
159	   * will be only called once with has_more_results set to false.
160	   */
161	  auto handler = [promise,
162	                  &final_status](const hdfs::Status &status,
163	                                 const std::vector<hdfs::StatInfo> &stat_info,
164	                                 const bool has_more_results) -> bool {
165	    // Print result chunks as they arrive
166	    if (!stat_info.empty()) {
167	      for (hdfs::StatInfo const &info : stat_info) {
168	        std::cout << info.str() << std::endl;
169	      }
170	    }
171	    if (!status.ok() && final_status.ok()) {
172	      // We make sure we set 'status' only on the first error
173	      final_status = status;
174	    }
175	    if (!has_more_results) {
176	      promise->set_value(); // Set promise
177	      return false;         // Request stop sending results
178	    }
179	    return true; // request more results
180	  };
181	
182	  // Asynchronous call to Find
183	  fs->Find(uri.get_path(), name, max_depth, handler);
184	
185	  // Block until promise is set
186	  future.get();
187	  if (!final_status.ok()) {
188	    std::cerr << "Error: " << final_status.ToString() << std::endl;
189	    return false;
190	  }
191	  return true;
192	}
