315	            // thread is already stopped. No need to acquire any other lock.
316	            editsTailed = doTailEdits();
317	          } catch (InterruptedException e) {
318	            throw new IOException(e);
319	          } finally {
320	            NameNode.getNameNodeMetrics().addEditLogTailTime(
