329	  @VisibleForTesting
330	  public long doTailEdits() throws IOException, InterruptedException {
331	    // Write lock needs to be interruptible here because the 
332	    // transitionToActive RPC takes the write lock before calling
333	    // tailer.stop() -- so if we're not interruptible, it will
334	    // deadlock.
335	    namesystem.writeLockInterruptibly();
336	    try {
337	      FSImage image = namesystem.getFSImage();
338	
339	      long lastTxnId = image.getLastAppliedTxId();
340	      
341	      if (LOG.isDebugEnabled()) {
342	        LOG.debug("lastTxnId: " + lastTxnId);
343	      }
344	      Collection<EditLogInputStream> streams;
345	      long startTime = timer.monotonicNow();
346	      try {
347	        streams = editLog.selectInputStreams(lastTxnId + 1, 0,
348	            null, inProgressOk, true);
349	      } catch (IOException ioe) {
350	        // This is acceptable. If we try to tail edits in the middle of an edits
351	        // log roll, i.e. the last one has been finalized but the new inprogress
352	        // edits file hasn't been started yet.
353	        LOG.warn("Edits tailer failed to find any streams. Will try again " +
354	            "later.", ioe);
355	        return 0;
356	      } finally {
357	        NameNode.getNameNodeMetrics().addEditLogFetchTime(
358	            timer.monotonicNow() - startTime);
359	      }
360	      if (LOG.isDebugEnabled()) {
361	        LOG.debug("edit streams to load from: " + streams.size());
362	      }
363	      
364	      // Once we have streams to load, errors encountered are legitimate cause
365	      // for concern, so we don't catch them here. Simple errors reading from
366	      // disk are ignored.
367	      long editsLoaded = 0;
368	      try {
369	        editsLoaded = image.loadEdits(
370	            streams, namesystem, maxTxnsPerLock, null, null);
371	      } catch (EditLogInputException elie) {
372	        editsLoaded = elie.getNumEditsLoaded();
373	        throw elie;
374	      } finally {
375	        if (editsLoaded > 0 || LOG.isDebugEnabled()) {
376	          LOG.debug(String.format("Loaded %d edits starting from txid %d ",
377	              editsLoaded, lastTxnId));
378	        }
379	        NameNode.getNameNodeMetrics().addNumEditLogLoaded(editsLoaded);
380	      }
381	
382	      if (editsLoaded > 0) {
383	        lastLoadTimeMs = timer.monotonicNow();
384	      }
385	      lastLoadedTxnId = image.getLastAppliedTxId();
386	      return editsLoaded;
387	    } finally {
388	      namesystem.writeUnlock();
389	    }
390	  }
