208	  private <T> T doAsExternalCall(final UserGroupInformation ugi,
209	      final PrivilegedExceptionAction<T> action)
210	          throws IOException, InterruptedException {
211	    // set the remote address, if coming in via a trust proxy server then
212	    // the address with be that of the proxied client
213	    ExternalCall<T> call = new ExternalCall<T>(action){
214	      @Override
215	      public UserGroupInformation getRemoteUser() {
216	        return ugi;
