218	      @Override
219	      public String getProtocol() {
220	        return "webhdfs";
221	      }
222	      @Override
223	      public String getHostAddress() {
224	        return getRemoteAddr();
225	      }
226	      @Override
227	      public InetAddress getHostInetAddress() {
228	        try {
229	          return InetAddress.getByName(getHostAddress());
230	        } catch (UnknownHostException e) {
231	          return null;
232	        }
233	      }
234	    };
235	
236	    queueExternalCall(call);
237	    T result = null;
238	    try {
239	      result = call.get();
240	    } catch (ExecutionException ee) {
241	      Throwable t = ee.getCause();
242	      if (t instanceof RuntimeException) {
243	        throw (RuntimeException)t;
244	      } else if (t instanceof IOException) {
245	        throw (IOException)t;
246	      } else {
247	        throw new IOException(t);
248	      }
249	    }
250	    return result;
251	  }
