758	  /**
759	   * Authorizes the request and returns the application specific request
760	   * processing pipeline.
761	   *
762	   * @return the the intercepter wrapper instance
763	   * @throws YarnException if fails
764	   */
765	  private RequestInterceptorChainWrapper authorizeAndGetInterceptorChain()
766	      throws YarnException {
767	    AMRMTokenIdentifier tokenIdentifier =
768	        YarnServerSecurityUtils.authorizeRequest();
769	    return getInterceptorChain(tokenIdentifier);
