772	  private RequestInterceptorChainWrapper getInterceptorChain(
773	      AMRMTokenIdentifier tokenIdentifier) throws YarnException {
774	    ApplicationAttemptId appAttemptId =
775	        tokenIdentifier.getApplicationAttemptId();
776	
777	    synchronized (this.applPipelineMap) {
778	      if (!this.applPipelineMap.containsKey(appAttemptId
779	          .getApplicationId())) {
780	        throw new YarnException(
781	            "The AM request processing pipeline is not initialized for app: "
782	                + appAttemptId.getApplicationId().toString());
783	      }
784	
785	      return this.applPipelineMap.get(appAttemptId.getApplicationId());
786	    }
