namespace hdfs::tools {
/**
 * {@class Find} is an {@class HdfsTool} that finds all files recursively
 * starting from the specified path and prints their file paths. This tool
 * mimics the POSIX find.
 */
class Find : public HdfsTool {
public:
  /**
   * {@inheritdoc}
   */
  Find(int argc, char **argv);

  // Abiding to the Rule of 5
  Find(const Find &) = default;
  Find(Find &&) = default;
  Find &operator=(const Find &) = delete;
  Find &operator=(Find &&) = delete;
  ~Find() override = default;

  /**
   * {@inheritdoc}
   */
  [[nodiscard]] std::string GetDescription() const override;

  /**
   * {@inheritdoc}
   */
  [[nodiscard]] bool Do() override;

protected:
  /**
   * {@inheritdoc}
   */
  [[nodiscard]] bool Initialize() override;

  /**
   * {@inheritdoc}
   */
  [[nodiscard]] bool ValidateConstraints() const override { return argc_ > 1; }

  /**
   * {@inheritdoc}
   */
  [[nodiscard]] bool HandleHelp() const override;

  /**
   * Handle the path argument that's passed to this tool.
   *
   * @param path The path where we want to start the find operation.
   * @param name If provided, all results will be matching the name pattern,
   * otherwise, the implicit '*' will be used.
   * @param max_depth If provided, the maximum depth to recurse after the end of
   * the path is reached will be limited by this value, otherwise, the maximum
   * depth to recurse is unbound.
   *
   * @return A boolean indicating the result of this operation.
   */
  [[nodiscard]] virtual bool HandlePath(const std::string &path,
                                        const std::string &name,
                                        uint32_t max_depth) const;

private:
  /**
   * A boost data-structure containing the description of positional arguments
   * passed to the command-line.
   */
  po::positional_options_description pos_opt_desc_;
};
} // namespace hdfs::tools
#endif

