396	  /**
397	   * Get a URI to redirect an operation to.
398	   * @param router Router to check.
399	   * @param ugi User group information.
400	   * @param delegation Delegation token.
401	   * @param username User name.
402	   * @param doAsUser Do as user.
403	   * @param path Path to check.
404	   * @param op Operation to perform.
405	   * @param openOffset Offset for opening a file.
406	   * @param excludeDatanodes Blocks to excluded.
407	   * @param parameters Other parameters.
408	   * @return Redirection URI.
409	   * @throws URISyntaxException If it cannot parse the URI.
410	   * @throws IOException If it cannot create the URI.
411	   */
412	  private URI redirectURI(final Router router, final UserGroupInformation ugi,
413	      final DelegationParam delegation, final UserParam username,
414	      final DoAsParam doAsUser, final String path, final HttpOpParam.Op op,
415	      final long openOffset, final String excludeDatanodes,
416	      final Param<?, ?>... parameters) throws URISyntaxException, IOException {
417	    final DatanodeInfo dn =
418	        chooseDatanode(router, path, op, openOffset, excludeDatanodes);
419	
420	    if (dn == null) {
421	      throw new IOException("Failed to find datanode, suggest to check cluster"
422	          + " health. excludeDatanodes=" + excludeDatanodes);
423	    }
424	
425	    final String delegationQuery;
426	    if (!UserGroupInformation.isSecurityEnabled()) {
427	      // security disabled
428	      delegationQuery = Param.toSortedString("&", doAsUser, username);
429	    } else if (delegation.getValue() != null) {
430	      // client has provided a token
431	      delegationQuery = "&" + delegation;
432	    } else {
433	      // generate a token
434	      final Token<? extends TokenIdentifier> t = generateDelegationToken(
435	          ugi, ugi.getUserName());
436	      delegationQuery = "&delegation=" + t.encodeToUrlString();
437	    }
438	
439	    final String redirectQuery = op.toQueryString() + delegationQuery
440	        + "&namenoderpcaddress=" + router.getRouterId()
441	        + Param.toSortedString("&", parameters);
442	    final String uripath = WebHdfsFileSystem.PATH_PREFIX + path;
443	
444	    int port = "http".equals(getScheme()) ? dn.getInfoPort() :
445	        dn.getInfoSecurePort();
446	    final URI uri = new URI(getScheme(), null, dn.getHostName(), port, uripath,
447	        redirectQuery, null);
448	
449	    if (LOG.isTraceEnabled()) {
450	      LOG.trace("redirectURI={}", uri);
451	    }
452	    return uri;
453	  }
454	
455	  private DatanodeInfo chooseDatanode(final Router router,
456	      final String path, final HttpOpParam.Op op, final long openOffset,
457	      final String excludeDatanodes) throws IOException {
458	    final RouterRpcServer rpcServer = getRPCServer(router);
459	    DatanodeInfo[] dns = {};
460	    String resolvedNs = "";
461	    try {
462	      dns = rpcServer.getCachedDatanodeReport(DatanodeReportType.LIVE);
463	    } catch (IOException e) {
464	      LOG.error("Cannot get the datanodes from the RPC server", e);
465	    }
466	
467	    if (op == PutOpParam.Op.CREATE) {
468	      try {
469	        resolvedNs = rpcServer.getCreateLocation(path).getNameserviceId();
470	      } catch (IOException e) {
471	        LOG.error("Cannot get the name service " +
472	            "to create file for path {} ", path, e);
473	      }
474	    }
475	
476	    HashSet<Node> excludes = new HashSet<Node>();
477	    Collection<String> collection =
478	        getTrimmedStringCollection(excludeDatanodes);
479	    for (DatanodeInfo dn : dns) {
480	      String ns = getNsFromDataNodeNetworkLocation(dn.getNetworkLocation());
481	      if (collection.contains(dn.getName())) {
482	        excludes.add(dn);
483	      } else if (op == PutOpParam.Op.CREATE && !ns.equals(resolvedNs)) {
484	        // for CREATE, the dest dn should be in the resolved ns
485	        excludes.add(dn);
486	      }
487	    }
488	
489	    if (op == GetOpParam.Op.OPEN ||
490	        op == PostOpParam.Op.APPEND ||
491	        op == GetOpParam.Op.GETFILECHECKSUM) {
492	      // Choose a datanode containing a replica
493	      final ClientProtocol cp = getRpcClientProtocol();
494	      final HdfsFileStatus status = cp.getFileInfo(path);
495	      if (status == null) {
496	        throw new FileNotFoundException("File " + path + " not found.");
497	      }
498	      final long len = status.getLen();
499	      if (op == GetOpParam.Op.OPEN) {
500	        if (openOffset < 0L || (openOffset >= len && len > 0)) {
501	          throw new IOException("Offset=" + openOffset
502	              + " out of the range [0, " + len + "); " + op + ", path=" + path);
503	        }
504	      }
505	
506	      if (len > 0) {
507	        final long offset = op == GetOpParam.Op.OPEN ? openOffset : len - 1;
508	        final LocatedBlocks locations = cp.getBlockLocations(path, offset, 1);
509	        final int count = locations.locatedBlockCount();
510	        if (count > 0) {
511	          LocatedBlock location0 = locations.get(0);
512	          return bestNode(location0.getLocations(), excludes);
513	        }
514	      }
515	    }
516	
517	    return getRandomDatanode(dns, excludes);
518	  }
519	
520	  /**
521	   * Get the nameservice info from datanode network location.
522	   * @param location network location with format `/ns0/rack1`
523	   * @return nameservice this datanode is in
524	   */
525	  @VisibleForTesting
526	  public static String getNsFromDataNodeNetworkLocation(String location) {
527	    // network location should be in the format of /ns/rack
528	    Pattern pattern = Pattern.compile("^/([^/]*)/");
529	    Matcher matcher = pattern.matcher(location);
530	    if (matcher.find()) {
531	      return matcher.group(1);
532	    }
533	    return "";
534	  }
535	
536	  /**
537	   * Get a random Datanode from a subcluster.
538	   * @param dns Nodes to be chosen from.
539	   * @param excludes Nodes to be excluded from.
540	   * @return Random datanode from a particular subluster.
541	   */
542	  private static DatanodeInfo getRandomDatanode(
543	      final DatanodeInfo[] dns, final HashSet<Node> excludes) {
544	    DatanodeInfo dn = null;
545	
546	    if (dns == null) {
547	      return dn;
548	    }
549	
550	    int numDNs = dns.length;
551	    int availableNodes = 0;
552	    if (excludes.isEmpty()) {
553	      availableNodes = numDNs;
554	    } else {
555	      for (DatanodeInfo di : dns) {
556	        if (!excludes.contains(di)) {
557	          availableNodes++;
558	        }
559	      }
560	    }
561	
562	    // Return a random one from the list
563	    if (availableNodes > 0) {
564	      while (dn == null || excludes.contains(dn)) {
565	        Random rnd = new Random();
566	        int idx = rnd.nextInt(numDNs);
567	        dn = dns[idx];
568	      }
569	    }
570	    return dn;
571	  }
572	
573	  /**
574	   * Generate the credentials for this request.
575	   * @param ugi User group information.
576	   * @param renewer Who is asking for the renewal.
577	   * @return Credentials holding delegation token.
578	   * @throws IOException If it cannot create the credentials.
579	   */
580	  @Override
581	  public Credentials createCredentials(
582	      final UserGroupInformation ugi,
583	      final String renewer) throws IOException {
584	    final Router router = (Router)getContext().getAttribute("name.node");
585	    final Credentials c = RouterSecurityManager.createCredentials(router, ugi,
586	        renewer != null? renewer: ugi.getShortUserName());
587	    return c;
588	  }
589	}

