14	 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
15	 * See the License for the specific language governing permissions and
16	 * limitations under the License.
17	 */
18	
19	package org.apache.hadoop.mapred.lib.aggregate;
20	
21	import java.io.IOException;
22	import java.util.ArrayList;
23	
24	import org.apache.hadoop.classification.InterfaceAudience;
25	import org.apache.hadoop.classification.InterfaceStability;
26	import org.apache.hadoop.conf.Configuration;
27	import org.apache.hadoop.fs.Path;
28	import org.apache.hadoop.io.Text;
29	import org.apache.hadoop.mapred.FileInputFormat;
30	import org.apache.hadoop.mapred.FileOutputFormat;
31	import org.apache.hadoop.mapred.InputFormat;
32	import org.apache.hadoop.mapred.JobClient;
33	import org.apache.hadoop.mapred.JobConf;
34	import org.apache.hadoop.mapred.SequenceFileInputFormat;
35	import org.apache.hadoop.mapred.TextInputFormat;
36	import org.apache.hadoop.mapred.TextOutputFormat;
37	import org.apache.hadoop.mapred.jobcontrol.Job;
38	import org.apache.hadoop.mapred.jobcontrol.JobControl;
39	import org.apache.hadoop.util.GenericOptionsParser;
40	
41	/**
42	 * This is the main class for creating a map/reduce job using Aggregate
43	 * framework. The Aggregate is a specialization of map/reduce framework,
44	 * specilizing for performing various simple aggregations.
45	 * 
46	 * Generally speaking, in order to implement an application using Map/Reduce
47	 * model, the developer is to implement Map and Reduce functions (and possibly
48	 * combine function). However, a lot of applications related to counting and
49	 * statistics computing have very similar characteristics. Aggregate abstracts
50	 * out the general patterns of these functions and implementing those patterns.
51	 * In particular, the package provides generic mapper/redducer/combiner classes,
52	 * and a set of built-in value aggregators, and a generic utility class that
53	 * helps user create map/reduce jobs using the generic class. The built-in
54	 * aggregators include:
55	 * 
56	 * sum over numeric values count the number of distinct values compute the
57	 * histogram of values compute the minimum, maximum, media,average, standard
58	 * deviation of numeric values
59	 * 
60	 * The developer using Aggregate will need only to provide a plugin class
61	 * conforming to the following interface:
62	 * 
63	 * public interface ValueAggregatorDescriptor { public ArrayList&lt;Entry&gt;
64	 * generateKeyValPairs(Object key, Object value); public void
65	 * configure(JobConfjob); }
66	 * 
67	 * The package also provides a base class, ValueAggregatorBaseDescriptor,
68	 * implementing the above interface. The user can extend the base class and
69	 * implement generateKeyValPairs accordingly.
70	 * 
71	 * The primary work of generateKeyValPairs is to emit one or more key/value
72	 * pairs based on the input key/value pair. The key in an output key/value pair
73	 * encode two pieces of information: aggregation type and aggregation id. The
74	 * value will be aggregated onto the aggregation id according the aggregation
75	 * type.
76	 * 
77	 * This class offers a function to generate a map/reduce job using Aggregate
78	 * framework. The function takes the following parameters: input directory spec
79	 * input format (text or sequence file) output directory a file specifying the
80	 * user plugin class
81	 */
82	@InterfaceAudience.Public
83	@InterfaceStability.Stable
84	public class ValueAggregatorJob {
85	
86	  public static JobControl createValueAggregatorJobs(String args[]
87	    , Class<? extends ValueAggregatorDescriptor>[] descriptors) throws IOException {
88	    
89	    JobControl theControl = new JobControl("ValueAggregatorJobs");
90	    ArrayList<Job> dependingJobs = new ArrayList<Job>();
91	    JobConf aJobConf = createValueAggregatorJob(args);
92	    if(descriptors != null)
93	      setAggregatorDescriptors(aJobConf, descriptors);
94	    Job aJob = new Job(aJobConf, dependingJobs);
95	    theControl.addJob(aJob);
96	    return theControl;
97	  }
98	
99	  public static JobControl createValueAggregatorJobs(String args[]) throws IOException {
100	    return createValueAggregatorJobs(args, null);
101	  }
102	  
103	  /**
104	   * Create an Aggregate based map/reduce job.
105	   *
106	   * @param args the arguments used for job creation. Generic hadoop
107	   * arguments are accepted.
108	   * @param caller the the caller class.
109	   * @return a JobConf object ready for submission.
110	   *
111	   * @throws IOException
112	   * @see GenericOptionsParser
113	   */
114	  @SuppressWarnings("rawtypes")
115	  public static JobConf createValueAggregatorJob(String args[], Class<?> caller)
116	    throws IOException {
117	
118	    Configuration conf = new Configuration();
119	    
120	    GenericOptionsParser genericParser 
121	      = new GenericOptionsParser(conf, args);
122	    args = genericParser.getRemainingArgs();
123	    
124	    if (args.length < 2) {
125	      System.out.println("usage: inputDirs outDir "
126	          + "[numOfReducer [textinputformat|seq [specfile [jobName]]]]");
127	      GenericOptionsParser.printGenericCommandUsage(System.out);
128	      System.exit(1);
129	    }
130	    String inputDir = args[0];
131	    String outputDir = args[1];
132	    int numOfReducers = 1;
133	    if (args.length > 2) {
134	      numOfReducers = Integer.parseInt(args[2]);
135	    }
136	
137	    Class<? extends InputFormat> theInputFormat =
138	      TextInputFormat.class;
139	    if (args.length > 3 && 
140	        args[3].compareToIgnoreCase("textinputformat") == 0) {
141	      theInputFormat = TextInputFormat.class;
142	    } else {
143	      theInputFormat = SequenceFileInputFormat.class;
144	    }
145	
146	    Path specFile = null;
147	
148	    if (args.length > 4) {
149	      specFile = new Path(args[4]);
150	    }
151	
152	    String jobName = "";
153	    
154	    if (args.length > 5) {
155	      jobName = args[5];
156	    }
157	    
158	    JobConf theJob = new JobConf(conf);
159	    if (specFile != null) {
160	      theJob.addResource(specFile);
161	    }
162	    String userJarFile = theJob.get("user.jar.file");
163	    if (userJarFile == null) {
164	      theJob.setJarByClass(caller != null ? caller : ValueAggregatorJob.class);
165	    } else {
166	      theJob.setJar(userJarFile);
167	    }
168	    theJob.setJobName("ValueAggregatorJob: " + jobName);
169	
170	    FileInputFormat.addInputPaths(theJob, inputDir);
171	
172	    theJob.setInputFormat(theInputFormat);
173	    
174	    theJob.setMapperClass(ValueAggregatorMapper.class);
175	    FileOutputFormat.setOutputPath(theJob, new Path(outputDir));
176	    theJob.setOutputFormat(TextOutputFormat.class);
177	    theJob.setMapOutputKeyClass(Text.class);
178	    theJob.setMapOutputValueClass(Text.class);
179	    theJob.setOutputKeyClass(Text.class);
180	    theJob.setOutputValueClass(Text.class);
181	    theJob.setReducerClass(ValueAggregatorReducer.class);
182	    theJob.setCombinerClass(ValueAggregatorCombiner.class);
183	    theJob.setNumMapTasks(1);
184	    theJob.setNumReduceTasks(numOfReducers);
185	    return theJob;
186	  }
187	
188	  /**
189	   * Create an Aggregate based map/reduce job.
190	   * 
191	   * @param args the arguments used for job creation. Generic hadoop
192	   * arguments are accepted.
193	   * @return a JobConf object ready for submission.
194	   * 
195	   * @throws IOException
196	   * @see GenericOptionsParser
197	   */
198	  public static JobConf createValueAggregatorJob(String args[])
199	    throws IOException {
200	    return createValueAggregatorJob(args, ValueAggregator.class);
201	  }
202	
203	  public static JobConf createValueAggregatorJob(String args[]
204	    , Class<? extends ValueAggregatorDescriptor>[] descriptors)
205	  throws IOException {
206	    JobConf job = createValueAggregatorJob(args);
207	    setAggregatorDescriptors(job, descriptors);
208	    return job;
209	  }
210	  
211	  public static void setAggregatorDescriptors(JobConf job
212	      , Class<? extends ValueAggregatorDescriptor>[] descriptors) {
213	    job.setInt("aggregator.descriptor.num", descriptors.length);
214	    //specify the aggregator descriptors
215	    for(int i=0; i< descriptors.length; i++) {
216	      job.set("aggregator.descriptor." + i, "UserDefined," + descriptors[i].getName());
217	    }    
218	  }
219	
220	  public static JobConf createValueAggregatorJob(String args[],
221	      Class<? extends ValueAggregatorDescriptor>[] descriptors,
222	      Class<?> caller) throws IOException {
223	    JobConf job = createValueAggregatorJob(args, caller);
224	    setAggregatorDescriptors(job, descriptors);
225	    return job;
226	  }
227	
228	  /**
229	   * create and run an Aggregate based map/reduce job.
230	   * 
231	   * @param args the arguments used for job creation
232	   * @throws IOException
233	   */
234	  public static void main(String args[]) throws IOException {
235	    JobConf job = ValueAggregatorJob.createValueAggregatorJob(args);
236	    JobClient.runJob(job);
237	  }
238	}

