60	    String output = new String(out.toByteArray(), Charsets.UTF_8);
61	
62	    if (!errOutput.matches(string) && !output.matches(string)) {
63	      fail("Expected output to match '" + string +
64	          "' but err_output was:\n" + errOutput +
65	          "\n and output was: \n" + output);
