95	   *
96	   * @param fs                AzureBlobFileSystem
97	   * @param path              Path of the file
98	   * @param originalByteArray original byte array
99	   * @return if content is validated true else, false
100	   * @throws IOException
101	   */
102	  protected boolean validateContent(AzureBlobFileSystem fs, Path path,
103	      byte[] originalByteArray)
104	      throws IOException {
105	    int pos = 0;
106	    int lenOfOriginalByteArray = originalByteArray.length;
107	
108	    try (FSDataInputStream in = fs.open(path)) {
109	      byte valueOfContentAtPos = (byte) in.read();
110	
111	      while (valueOfContentAtPos != -1 && pos < lenOfOriginalByteArray) {
112	        if (originalByteArray[pos] != valueOfContentAtPos) {
113	          assertEquals("Mismatch in content validation at position {}", pos,
114	              originalByteArray[pos], valueOfContentAtPos);
115	          return false;
116	        }
117	        valueOfContentAtPos = (byte) in.read();
118	        pos++;
119	      }
120	      if (valueOfContentAtPos != -1) {
121	        assertEquals("Expected end of file", -1, valueOfContentAtPos);
122	        return false;
123	      }
124	      return true;
125	    }
