boolean updateHost2DatanodeMap = false;
if (nodeS != null) {
  if (nodeN == nodeS) {
    // The same datanode has been just restarted to serve the same data 
    // storage. We do not need to remove old data blocks, the delta will
    // be calculated on the next block report from the datanode
    if(NameNode.stateChangeLog.isDebugEnabled()) {
      NameNode.stateChangeLog.debug("BLOCK* registerDatanode: "
          + "node restarted.");
    }
  } else {
    // nodeS is found
    /* The registering datanode is a replacement node for the existing 
      data storage, which from now on will be served by a new node.
      If this message repeats, both nodes might have same storageID 
      by (insanely rare) random chance. User needs to restart one of the
      nodes with its data cleared (or user can just remove the StorageID
      value in "VERSION" file under the data directory of the datanode,
      but this is might not work if VERSION file format has changed 
   */
    // Check if nodeS's host information is same as nodeReg's, if not,
    // it needs to update host2DatanodeMap accordingly.
    updateHost2DatanodeMap =
        !nodeS.getXferAddr().equals(nodeReg.getXferAddr());

    NameNode.stateChangeLog.info("BLOCK* registerDatanode: " + nodeS
        + " is replaced by " + nodeReg + " with the same storageID "
        + nodeReg.getDatanodeUuid());
  }

  if (!updateHost2DatanodeMap) {
    updateHost2DatanodeMap =
        !nodeS.getHostName().equals(nodeReg.getHostName());
  }

  boolean success = false;
  try {
    // update cluster map
    getNetworkTopology().remove(nodeS);

    // Update Host2DatanodeMap
    if (updateHost2DatanodeMap) {
      getHost2DatanodeMap().remove(nodeS);
    }
    if(shouldCountVersion(nodeS)) {
      decrementVersionCount(nodeS.getSoftwareVersion());
    }
    nodeS.updateRegInfo(nodeReg);

